package com.eventdrivencommerce.order.configuration;
import org.apache.kafka.common.TopicPartition;import org.springframework.context.annotation.*;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.kafka.listener.DefaultErrorHandler;import org.springframework.kafka.listener.DeadLetterPublishingRecoverer;import org.springframework.util.backoff.ExponentialBackOff;
@Configuration public class KafkaConfiguration {@Bean DefaultErrorHandler kafkaErrorHandler(KafkaTemplate<Object,Object> template){var recoverer=new DeadLetterPublishingRecoverer(template,(record,ex)->new TopicPartition(record.topic()+".dlt",record.partition()));var backoff=new ExponentialBackOff(500,2);backoff.setMaxInterval(5000);backoff.setMaxElapsedTime(15000);return new DefaultErrorHandler(recoverer,backoff);}}
